import React from 'react';
import './PlaylistDetailPage.css';

const mockPlaylist = {
  playlistId: 1,
  title: 'Happy Vibes',
  mood: 'happy',
  createdAt: 'March 28, 2026',
  contextNote: 'Feeling happy and excited about my project progress!',
  tracks: [
    { trackId: 1, trackOrder: 1, trackName: 'Walking on Sunshine', artistName: 'Katrina & The Waves', youtubeMusicUrl: 'https://music.youtube.com' },
    { trackId: 2, trackOrder: 2, trackName: 'Happy', artistName: 'Pharrell Williams', youtubeMusicUrl: 'https://music.youtube.com' },
    { trackId: 3, trackOrder: 3, trackName: 'Good as Hell', artistName: 'Lizzo', youtubeMusicUrl: 'https://music.youtube.com' },
    { trackId: 4, trackOrder: 4, trackName: "Don't Stop Me Now", artistName: 'Queen', youtubeMusicUrl: 'https://music.youtube.com' },
    { trackId: 5, trackOrder: 5, trackName: 'Uptown Funk', artistName: 'Bruno Mars', youtubeMusicUrl: 'https://music.youtube.com' },
  ],
};

function PlaylistDetailPage() {
  return (
    <div className="detail-container">
      <button className="back-btn" onClick={() => window.history.back()}>← Back to Library</button>

      <div className="detail-header">
        <h1 className="detail-title">{mockPlaylist.title}</h1>
        <p className="detail-meta">Generated on {mockPlaylist.createdAt} · {mockPlaylist.tracks.length} songs</p>
        <div className="detail-context">"{mockPlaylist.contextNote}"</div>
        <div className="detail-actions">
          <button className="btn-share">Share with Friends</button>
        </div>
      </div>

      <div className="track-list">
        {mockPlaylist.tracks.map(track => (
          <div key={track.trackId} className="track-row">
            <span className="track-order">{track.trackOrder}</span>
            <div className="track-info">
              <span className="track-name">{track.trackName}</span>
              <span className="track-artist">{track.artistName}</span>
            </div>
            
              href={track.youtubeMusicUrl}
              target="_blank"
              rel="noreferrer"
              className="yt-link"
            <a>
              ▶ YouTube Music
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}

export default PlaylistDetailPage;
